//! `#[pg_function]`: the Rust half of a sutegi-pgext SQL function.
//!
//! The macro emits an `extern "C"` wrapper, `sutegi_pgext_fn_<name>`, that
//! the C glue generated by `sutegi pgext build` calls. The SQL half (the
//! `CREATE FUNCTION` statement) comes from the same signature, scanned by the
//! build; the options are validated here so a typo fails at compile time.

use proc_macro2::TokenStream;
use quote::{format_ident, quote};
use syn::parse::Parser;
use syn::punctuated::Punctuated;
use syn::{FnArg, ItemFn, Meta, Token};

const FLAGS: &[&str] = &[
    "immutable",
    "stable",
    "volatile",
    "parallel_safe",
    "parallel_restricted",
    "parallel_unsafe",
    "leakproof",
    "security_definer",
];

fn check_options(attr: TokenStream) -> syn::Result<()> {
    let metas = Punctuated::<Meta, Token![,]>::parse_terminated.parse2(attr)?;
    let mut volatility = 0;
    let mut parallel = 0;
    for meta in metas {
        match &meta {
            Meta::Path(p) => {
                let name = p.get_ident().map(ToString::to_string).unwrap_or_default();
                if !FLAGS.contains(&name.as_str()) {
                    return Err(syn::Error::new_spanned(
                        p,
                        format!(
                            "unknown pg_function option; expected one of {}, name = \"..\", cost = N, rows = N",
                            FLAGS.join(", ")
                        ),
                    ));
                }
                if matches!(name.as_str(), "immutable" | "stable" | "volatile") {
                    volatility += 1;
                }
                if name.starts_with("parallel_") {
                    parallel += 1;
                }
            }
            Meta::NameValue(nv) => {
                let key = nv
                    .path
                    .get_ident()
                    .map(ToString::to_string)
                    .unwrap_or_default();
                let lit = match &nv.value {
                    syn::Expr::Lit(l) => &l.lit,
                    other => return Err(syn::Error::new_spanned(other, "expected a literal")),
                };
                match (key.as_str(), lit) {
                    ("name", syn::Lit::Str(s)) => {
                        let v = s.value();
                        let ok = v
                            .chars()
                            .next()
                            .is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                            && v.chars()
                                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
                            && v.len() <= 63;
                        if !ok {
                            return Err(syn::Error::new_spanned(
                                s,
                                "a SQL function name is [a-z_][a-z0-9_]*, at most 63 bytes",
                            ));
                        }
                    }
                    ("cost" | "rows", syn::Lit::Int(i)) => {
                        i.base10_parse::<u32>()?;
                    }
                    _ => {
                        return Err(syn::Error::new_spanned(
                            &meta,
                            "expected name = \"..\", cost = N or rows = N",
                        ));
                    }
                }
            }
            Meta::List(l) => return Err(syn::Error::new_spanned(l, "unexpected option list")),
        }
    }
    if volatility > 1 {
        return Err(syn::Error::new(
            proc_macro2::Span::call_site(),
            "pick one of immutable, stable, volatile",
        ));
    }
    if parallel > 1 {
        return Err(syn::Error::new(
            proc_macro2::Span::call_site(),
            "pick one parallel_* option",
        ));
    }
    Ok(())
}

pub(crate) fn expand(attr: TokenStream, item: TokenStream) -> syn::Result<TokenStream> {
    check_options(attr)?;
    let func: ItemFn = syn::parse2(item)?;
    let sig = &func.sig;
    if let Some(t) = sig.generics.type_params().next() {
        return Err(syn::Error::new_spanned(
            t,
            "a pg_function can't be generic over types",
        ));
    }
    if let Some(c) = sig.generics.const_params().next() {
        return Err(syn::Error::new_spanned(
            c,
            "a pg_function can't have const generics",
        ));
    }
    if let Some(a) = &sig.asyncness {
        return Err(syn::Error::new_spanned(a, "a pg_function can't be async"));
    }
    if let Some(u) = &sig.unsafety {
        return Err(syn::Error::new_spanned(u, "a pg_function can't be unsafe"));
    }
    if let Some(v) = &sig.variadic {
        return Err(syn::Error::new_spanned(
            v,
            "a pg_function can't be variadic",
        ));
    }

    let ident = &sig.ident;
    let wrapper = format_ident!("sutegi_pgext_fn_{}", ident);
    let name = ident.to_string();
    let mut reads = Vec::new();
    let mut args = Vec::new();
    for (i, input) in sig.inputs.iter().enumerate() {
        let FnArg::Typed(_) = input else {
            return Err(syn::Error::new_spanned(
                input,
                "a pg_function can't take self",
            ));
        };
        let var = format_ident!("__sx_arg{}", i);
        let index =
            i32::try_from(i).map_err(|_| syn::Error::new_spanned(input, "too many arguments"))?;
        reads.push(quote! {
            let #var = ::sutegi_pgext::__private::FromArg::from_arg(__sx_call, #index)?;
        });
        args.push(var);
    }
    let nargs = i32::try_from(args.len())
        .map_err(|_| syn::Error::new_spanned(sig, "too many arguments"))?;
    if nargs > 100 {
        return Err(syn::Error::new_spanned(
            &sig.inputs,
            "PostgreSQL functions take at most 100 arguments",
        ));
    }

    Ok(quote! {
        #func

        #[doc(hidden)]
        #[allow(unsafe_code, non_snake_case, clippy::missing_safety_doc, reason = "the C entry point of a pg_function")]
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn #wrapper(call: *mut ::sutegi_pgext::__private::RawCall) {
            // SAFETY: only the generated C glue calls this, passing the live
            // call sx_invoke set up for this invocation.
            unsafe {
                ::sutegi_pgext::__private::invoke(call, #name, #nargs, |__sx_call| {
                    #(#reads)*
                    ::sutegi_pgext::__private::IntoReturn::into_return(#ident(#(#args),*), __sx_call)
                })
            }
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn err(attr: &str, item: &str) -> String {
        let attr: TokenStream = attr.parse().unwrap();
        let item: TokenStream = item.parse().unwrap();
        expand(attr, item).unwrap_err().to_string()
    }

    #[test]
    fn rejects_unknown_options_and_conflicts() {
        assert!(err("imutable", "fn f() {}").contains("unknown pg_function option"));
        assert!(err("immutable, stable", "fn f() {}").contains("pick one"));
        assert!(err("name = \"Bad\"", "fn f() {}").contains("SQL function name"));
        assert!(err("cost = \"x\"", "fn f() {}").contains("expected name"));
    }

    #[test]
    fn rejects_unsupported_signatures() {
        assert!(err("", "fn f<T>(x: T) {}").contains("generic"));
        assert!(err("", "async fn f() {}").contains("async"));
        assert!(err("", "unsafe fn f() {}").contains("unsafe"));
    }

    #[test]
    fn emits_a_wrapper_per_function() {
        let out = expand(
            "immutable, parallel_safe, name = \"greet\""
                .parse()
                .unwrap(),
            "fn hello<'a>(name: &'a str) -> String { name.to_owned() }"
                .parse()
                .unwrap(),
        )
        .unwrap()
        .to_string();
        assert!(out.contains("sutegi_pgext_fn_hello"));
        assert!(out.contains("from_arg (__sx_call , 0i32)"));
    }
}
